function serializeQuery(pairs) {
  if (!Array.isArray(pairs)) {
    throw new TypeError("pairs must be an array");
  }

  const encoded = pairs.map((pair) => {
    if (!Array.isArray(pair) || pair.length !== 2) {
      throw new TypeError("each pair must be an array of length 2");
    }
    if (typeof pair[0] !== "string" || typeof pair[1] !== "string") {
      throw new TypeError("name and value must be strings");
    }

    return [encodeRFC3986(pair[0]), encodeRFC3986(pair[1])];
  });

  encoded.sort((a, b) => a[0] < b[0] ? -1 : a[0] > b[0] ? 1 :
    a[1] < b[1] ? -1 : a[1] > b[1] ? 1 : 0);

  return encoded.map(([name, value]) => name + "=" + value).join("&");
}

function encodeRFC3986(string) {
  const hex = "0123456789ABCDEF";
  let result = "";

  for (let i = 0; i < string.length; i++) {
    let code = string.charCodeAt(i);

    if (code >= 0xD800 && code <= 0xDBFF) {
      if (i + 1 >= string.length) {
        throw new URIError("unpaired surrogate");
      }
      const next = string.charCodeAt(++i);
      if (next < 0xDC00 || next > 0xDFFF) {
        throw new URIError("unpaired surrogate");
      }
      code = 0x10000 + ((code - 0xD800) << 10) + (next - 0xDC00);
    } else if (code >= 0xDC00 && code <= 0xDFFF) {
      throw new URIError("unpaired surrogate");
    }

    if (
      (code >= 0x41 && code <= 0x5A) ||
      (code >= 0x61 && code <= 0x7A) ||
      (code >= 0x30 && code <= 0x39) ||
      code === 0x2D || code === 0x2E || code === 0x5F || code === 0x7E
    ) {
      result += String.fromCodePoint(code);
      continue;
    }

    const bytes = code <= 0x7F ? [code] :
      code <= 0x7FF ? [
        0xC0 | (code >> 6),
        0x80 | (code & 0x3F)
      ] :
      code <= 0xFFFF ? [
        0xE0 | (code >> 12),
        0x80 | ((code >> 6) & 0x3F),
        0x80 | (code & 0x3F)
      ] : [
        0xF0 | (code >> 18),
        0x80 | ((code >> 12) & 0x3F),
        0x80 | ((code >> 6) & 0x3F),
        0x80 | (code & 0x3F)
      ];

    for (const byte of bytes) {
      result += "%" + hex[byte >> 4] + hex[byte & 0x0F];
    }
  }

  return result;
}
